"""G-CO.B: rigid motions, congruence, and the triangle congruence criteria (sets 11-16)."""
from qb import S, B, sa, mc, tf, plot
from common import gd, grid_fig, NTS, proof


def why(o, m, e):
    return 'Obstacle: %s Why it matters: %s Evidence: %s' % (o, m, e)


def two_tri(P1, P2, names2, desc, lo=-6, hi=6):
    P = dict(P1)
    P.update(P2)
    return grid_fig(P, [('poly', list(P1)), ('poly', list(P2))], lo=lo, hi=hi, names=names2, desc=desc)


TRI_SAS = gd({'A': (0, 0), 'B': (4, 0), 'C': (1.2, 2.6), 'D': (6, 0), 'E': (10, 0), 'F': (7.2, 2.6)},
             [('poly', ['A', 'B', 'C']), ('poly', ['D', 'E', 'F']),
              ('seg', 'A', 'B', {'ticks': 1}), ('seg', 'D', 'E', {'ticks': 1}),
              ('seg', 'A', 'C', {'ticks': 2}), ('seg', 'D', 'F', {'ticks': 2}),
              ('ang', 'A', 'B', 'C'), ('ang', 'D', 'E', 'F')], h=200,
             desc='Triangles ABC and DEF. AB and DE have one tick mark each, AC and DF have two tick marks each, and angles A and D '
                  'have one arc each, showing AB = DE, AC = DF, and angle A congruent to angle D.')

